//             EXPENSIVE STORAGE WRITE.
//         */
//         storedNumber = _num;
//     }

//     /*
//     =====================================================
//     STORAGE-HEAVY FUNCTION
//     =====================================================

//     Multiple storage writes.
//     */

//     function storeManyValues()
//         external
//     {

//         /*
//             Loop with storage writes.
//         */
//         for (
//             uint256 i = 0;
//             i < 10;
//             i++
//         ) {

//             /*
//                 VERY expensive.
//             */
//             values.push(i);
//         }
//     }

//     /*
//     =====================================================
//     VIEW ARRAY LENGTH
//     =====================================================

//     Cheap storage read.
//     */

//     function getArrayLength()
